"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[26856],{64405:e=>{e.exports=JSON.parse('{"functions":[{"name":"Apply","desc":"Swaps Lighting and the scenery to `biomeId`. Untagged post effects (e.g.\\nthe jump transition\'s blur) are left alone.","params":[{"name":"biomeId","desc":"Name of a folder in `ReplicatedStorage.Biome`; missing \u2192 `Normal`.","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":33,"path":"src/ReplicatedStorage/SharedModules/BiomeVisuals.luau"}}],"properties":[],"types":[],"name":"BiomeVisuals","desc":"Makes Lighting and the scenery match one biome. Each biome is a folder at\\n`ReplicatedStorage.Biome.<Id>`:\\n- attributes: Lighting property values (`Ambient`, `ClockTime`, ...)\\n- `Lighting/`: Sky, Atmosphere and post effects, cloned into Lighting\\n- `Scenery/`: cloned into `workspace.BiomeScenery`\\nA biome with no folder falls back to `Normal` (one warning per id).\\n\\nStudio preview from the command bar (revert to Normal before you save):\\n`require(game.ReplicatedStorage.SharedModules.BiomeVisuals).Apply(\\"Volcano\\")`","source":{"line":15,"path":"src/ReplicatedStorage/SharedModules/BiomeVisuals.luau"}}')}}]);